class DocumentArtifactCapabilities:
    """Frontend-facing choices for previewing and downloading a Document."""

    preview: DocumentPreviewMode = "markdown"
    download: DocumentDownloadMode = "markdown"
    source: bool = False

    def to_api(self) -> dict[str, str | bool]:
        return {"preview": self.preview, "download": self.download, **({"source": True} if self.source else {})}

def document_artifact_capabilities(
    *,
    name: str,
    content_uri: str | None,
    source_url: str | None,
    source_meta: dict[str, Any] | None,
) -> DocumentArtifactCapabilities:
    """Derive UI capabilities from the same persisted fields used by artifact resolution."""
    return DocumentArtifactCapabilities(
        preview=(
            "pdf"
            if document_has_pdf_preview(
                name=name,
                source_url=source_url,
                source_meta=source_meta,
            )
            else "markdown"
        ),
        download=(
            "artifact" if content_uri and document_is_read_only(content_uri=content_uri, source_meta=source_meta)
            else "markdown"
        ),
        source=bool(source_url),

def _resolve_document_artifact(
    body: DocumentBody,
    *,
    name: str,
    purpose: str,
) -> DocumentArtifact:
    if purpose not in {"source", "download", "preview"}:
        raise ValidationFailedError(
            "Invalid Document artifact purpose",
            details={"purpose": purpose},
        )

    source_uri = body.source_url
    if purpose == "source":
        if not source_uri:
            raise ValidationFailedError(
                "Document does not have an uploaded source artifact",
                details={"node_id": body.node_id},
            )
        return DocumentArtifact(node_id=body.node_id, name=name, uri=source_uri)

    if purpose == "preview":
        if not document_has_pdf_preview(
            name=name,
            source_url=source_uri,
            source_meta=body.source_meta,
        ):
            raise ValidationFailedError(
                "PDF preview is not available for this Document",
                details={"node_id": body.node_id},
            )
        return DocumentArtifact(node_id=body.node_id, name=name, uri=source_uri)

